"""Solar return, generated by us: the NYSE monthly solar-return charts and readings, Dec 2026 - Dec 2027, from what
Solar return has stated so far, with the transit rules it uses and the record of each piece.

    python tools/solar_return_generate.py

The method as reconstructed (tools/nyse_charts.py; validated on the 20 Oct and 19 Nov 2026 charts Solar return shared):
  * a month starts when the TROPICAL Sun reaches 27°18' of the next sign (the NYSE natal Sun); the chart is cast for
    New York and read with tropical signs and whole-sign houses;
  * monthly indications Solar return has stated: ascendant lord debilitated (bearish); Mars with Ketu in the 8th
    (bearish); a malefic (Mars, Saturn, Rahu, Ketu) in the 8th (bearish); Venus (or Jupiter) in the 10th moderates.
  * the reading is generated only from those statements:
        two bearish indications (debilitated ascendant lord and a malefic in the 8th)       -> "Bearish" (as 20 Oct)
        the same with Venus or Jupiter in the 10th                                           -> "Weak, moderated" (as 19 Nov)
        a malefic in the 8th only                                                            -> "Pressure"
        a debilitated ascendant lord only                                                    -> "Pressure"
        Venus or Jupiter in the 10th with no bearish indication                              -> "Supported"
        none of them                                                                         -> "No stated indication"
  * transit rules Solar return reads with degree aspects: Jupiter sextile Venus (bullish), Sun square Mars and
    Mars conjunct Ketu (bearish / disruption), Mars square Uranus (volatility), Mars retrograde, Mercury in Pisces.
Each piece carries its 1928-2026 S&P record (nyse_charts.py monthly backtest; author_forecasts.py transit tests).
A daily call in the same style, 24 Nov 2026 - 18 Jan 2027 (see day_call: calibrated on the 9 days Solar return called,
then run on every S&P session 1928-2026 to see what it is worth).
Writes build/pdfref/solar_return_generated_ET.{html,json}. Market prices and astrology only.
"""
from __future__ import annotations

import collections
import datetime as dt
import html
import json
import pathlib
import statistics
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
OUT = ROOT / "build" / "pdfref"
sys.path.insert(0, str(ROOT / "tools"))
from model_check_60d import load  # noqa: E402

NC = load(ROOT / "tools" / "nyse_charts.py", "ncg")
FD = load(ROOT / "tools" / "forward_daybyday.py", "fdg")
ET = NC.ET
BEAR_RULES = ("Sun square Mars (within 3°)", "Mars conjunct Ketu (within 5°)")


def reading(f):
    deb = f["Ascendant lord debilitated"]
    mal8 = f["Mars, Saturn, Rahu or Ketu in the 8th"]
    ten = f["Venus or Jupiter in the 10th"]
    if deb and mal8:
        return "Weak, moderated" if ten else "Bearish"
    if deb or mal8:
        return "Pressure"
    if ten:
        return "Supported"
    return "No stated indication"


LEAN = {"Bearish": -1, "Weak, moderated": -1, "Pressure": -1, "Supported": 1, "No stated indication": 0}


def history():
    _, months = NC.backtest("A")
    allr = [m["ret"] for m in months]
    by = collections.defaultdict(list)
    for m in months:
        by[reading(m["f"])].append(m["ret"])
    res = {}
    for k, v in by.items():
        res[k] = dict(n=len(v), up=round(sum(r > 0 for r in v) / len(v) * 100, 1), mean=round(statistics.fmean(v), 2),
                      fall5=round(sum(r <= -5 for r in v) / len(v) * 100, 1))
    bear = [r for m, r in zip(months, allr) if LEAN[reading(m["f"])] < 0]
    bull = [r for m, r in zip(months, allr) if LEAN[reading(m["f"])] > 0]
    calls = [(LEAN[reading(m["f"])], m["ret"]) for m in months if LEAN[reading(m["f"])]]
    right = sum((r > 0) == (l > 0) for l, r in calls)
    return dict(by=res, all=dict(n=len(allr), up=round(sum(r > 0 for r in allr) / len(allr) * 100, 1), mean=round(statistics.fmean(allr), 2),
                                 fall5=round(sum(r <= -5 for r in allr) / len(allr) * 100, 1)),
                calls=dict(n=len(calls), right=right, bear_n=len(bear), bear_up=round(sum(r > 0 for r in bear) / len(bear) * 100, 1) if bear else None,
                           bull_n=len(bull), bull_up=round(sum(r > 0 for r in bull) / len(bull) * 100, 1) if bull else None))


def months(a, b):
    out = []
    xs = NC.returns(a, b, 27.3, False)
    for x, nxt in zip(xs, xs[1:] + [None]):
        c = NC.chart(x, NC.NY[0], NC.NY[1], False)
        f = NC.features(c)
        d = NC.describe(c, False)
        p = {r["body"]: r for r in d["rows"]}
        ll = c["lagna_lord"]
        out.append(dict(start=NC.from_jd(x).astimezone(ET), end=NC.from_jd(nxt).astimezone(ET) if nxt else None, asc=d["asc"], lord=ll,
                        lord_pos=f"{p[ll]['sign']} {p[ll]['deg']}, house {p[ll]['house']}" + (" (debilitated)" if p[ll]["neecha"] else "") + (" R" if p[ll]["retro"] else ""),
                        h8=[b for b in p if p[b]["house"] == 8], h10=[b for b in p if p[b]["house"] == 10],
                        flags=[k for k, on in f.items() if on], reading=reading(f), rows=d["rows"]))
    return out


def episodes(a, b, atests):
    """Runs of days on which each Solar return transit rule is active (19:00 UT test time, as in author_forecasts.py)."""
    runs = collections.defaultdict(list)
    d = a
    while d <= b:
        on, detail = FD.author_rules(d)
        for k in on:
            key = k.split(" – ")[0]
            r = runs[key]
            if r and (d - r[-1]["to"]).days == 1:
                r[-1]["to"] = d
            else:
                r.append(dict(frm=d, to=d))
        d += dt.timedelta(days=1)
    out = []
    for k, lst in runs.items():
        t = next((v for kk, v in atests.items() if kk.startswith(k)), None)
        for r in lst:
            out.append(dict(rule=k, frm=r["frm"], to=r["to"], record=t))
    return sorted(out, key=lambda x: x["frm"])


def sep(detail, name):
    return float(detail.split(name + " ")[1].split("°")[0])


def day_call(d, month_reading):
    """Solar return-style call for one day. Calibrated on the 9 days Solar return called (16-27 Nov 2026): the bearish
    aspects take priority while active; Jupiter-Venus counts as bullish within 1° (Solar return named the exact days);
    Mars square Uranus alone = volatile; otherwise the month's reading."""
    on, detail = FD.author_rules(d)
    keys = [k.split(" – ")[0] for k in on]
    bear = [k for k in keys if k in BEAR_RULES]
    if bear:
        return "Bearish", ", ".join(bear), keys, detail
    if abs(sep(detail, "Jupiter–Venus") - 60) < 1:
        return "Bullish", "Jupiter sextile Venus (within 1°)", keys, detail
    if any(k.startswith("Mars square Uranus") for k in keys):
        return "Volatile", "Mars square Uranus", keys, detail
    lean = LEAN.get(month_reading, 0)
    return ({1: "Bullish", -1: "Bearish", 0: "No call"}[lean], f"month reading: {month_reading}" if month_reading else "", keys, detail)


def month_of(mons, d):
    return next((x for x in mons if x["start"].date() <= d and (x["end"] is None or d < x["end"].date())), None)


def daily(a, b, mons, atests):
    rows = []
    d = a
    while d <= b:
        if d.weekday() < 5 and d not in FD.CLOSED["spx"]:
            m = month_of(mons, d)
            call, why, keys, detail = day_call(d, m["reading"] if m else "")
            rows.append(dict(d=d, call=call, why=why, month=m["reading"] if m else "", active=keys, detail=detail))
        d += dt.timedelta(days=1)
    return rows


def backtest_daily():
    """The same daily call on every S&P session 1928 - 20 Nov 2026: same day and next 5 sessions (from the previous close)."""
    _, ms = NC.backtest("A")
    starts = [(m["start"].astimezone(ET).date(), reading(m["f"])) for m in ms]
    D, C = NC.spx()
    import bisect
    tally = collections.defaultdict(lambda: [0, 0, 0, 0])
    base = [0, 0, 0, 0]
    for i in range(1, len(D) - 5):
        d = D[i]
        if d < dt.date(1928, 2, 1) or d > dt.date(2026, 11, 13):
            continue
        k = bisect.bisect_right(START_DATES, d) - 1
        mr = starts[k][1] if k >= 0 else ""
        call = day_call(d, mr)[0]
        r1 = C[i] / C[i - 1] - 1
        r5 = C[i + 4] / C[i - 1] - 1
        base[0] += r1 > 0
        base[1] += 1
        base[2] += r5 > 0
        base[3] += 1
        if call in ("Bullish", "Bearish"):
            t = tally[call]
            t[0] += (r1 > 0) == (call == "Bullish")
            t[1] += 1
            t[2] += (r5 > 0) == (call == "Bullish")
            t[3] += 1
    out = {k: dict(d1=round(v[0] / v[1] * 100, 1), d5=round(v[2] / v[3] * 100, 1), n=v[1]) for k, v in tally.items()}
    up1, up5 = base[0] / base[1] * 100, base[2] / base[3] * 100
    out["_base"] = dict(up1=round(up1, 1), up5=round(up5, 1), n=base[1])
    allc = [tally["Bullish"], tally["Bearish"]]
    out["_all"] = dict(d1=round(sum(t[0] for t in allc) / sum(t[1] for t in allc) * 100, 1), d5=round(sum(t[2] for t in allc) / sum(t[3] for t in allc) * 100, 1),
                       n=sum(t[1] for t in allc))
    return out


START_DATES = []


def main():
    atests = json.load(open(OUT / "author_forecasts_ET.json"))["tests"]
    sr = json.load(open(OUT / "author_forecasts_ET.json"))["forecasts"]
    hist = history()
    _, ms = NC.backtest("A")
    START_DATES[:] = [m["start"].astimezone(ET).date() for m in ms]
    bt_daily = backtest_daily()
    mons = months(dt.datetime(2026, 10, 1), dt.datetime(2028, 1, 15))
    eps = episodes(dt.date(2026, 11, 24), dt.date(2027, 12, 31), atests)
    days = daily(dt.date(2026, 11, 24), dt.date(2027, 1, 18), mons, atests)
    # validation: generated vs what Solar return said
    val = []
    said = {"2026-10-20": "Bearish: debilitated ascendant lord Saturn and Mars with Ketu in the 8th",
            "2026-11-19": "Both persist, Venus in the 10th moderates: further weakness, smaller decline than -4.8%"}
    for m in mons:
        k = str(m["start"].date())
        if k in said:
            val.append(dict(month=k, generated=m["reading"], flags=m["flags"], said=said[k]))
    wk = {"2026-11-16": "down", "2026-11-17": "down", "2026-11-18": "down", "2026-11-19": "down", "2026-11-20": "up",
          "2026-11-23": "down", "2026-11-24": "down", "2026-11-25": "down", "2026-11-27": "up"}
    past = daily(dt.date(2026, 11, 16), dt.date(2026, 11, 27), mons, atests)
    wval = [dict(d=str(x["d"]), generated=x["call"], why=x["why"], said=wk.get(str(x["d"]), "")) for x in past if str(x["d"]) in wk]
    res = dict(hist=hist, bt_daily=bt_daily, months=mons, episodes=eps, days=days, validation=val, week_validation=wval, scorecard=sr, atests=atests)
    json.dump(res, open(OUT / "solar_return_generated_ET.json", "w"), indent=1, default=str)
    (OUT / "solar_return_generated_ET.html").write_text(page(res), encoding="utf-8")
    for m in mons:
        print(f"{m['start']:%a %d %b %Y %H:%M} asc {m['asc']:14s} lord {m['lord']:8s} {m['lord_pos']:32s} 8th {','.join(m['h8']) or '-':22s} 10th {','.join(m['h10']) or '-':22s} -> {m['reading']}")
    print(hist)
    for e in eps:
        print(e["rule"], e["frm"], e["to"])
    print(val)
    print(bt_daily)
    print(wval)


def page(res):
    E = html.escape
    css = """:root{color-scheme:light} body{margin:0;padding:16px;background:#fff;color:#1f2328;font:14px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:1250px}
h1{font-size:20px;margin:0 0 6px} h2{font-size:17px;margin:26px 0 8px;border-bottom:1px solid #d0d7de;padding-bottom:4px} h3{font-size:15px;margin:16px 0 6px}
.wrap{overflow-x:auto} table{border-collapse:collapse;width:100%;margin:4px 0 12px} th,td{border-bottom:1px solid #d0d7de;padding:5px 8px;text-align:left;vertical-align:top}
th{background:#f6f8fa} td.n{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap} .s{font-size:12px;color:#57606a}
.g{color:#1e7b3a;font-weight:600} .r{color:#b42318;font-weight:600} .v{color:#9a6700;font-weight:600} details{margin:6px 0} summary{cursor:pointer;color:#0969da}"""

    def cls(x):
        return "r" if x in ("Bearish", "Weak, moderated", "Pressure") else "g" if x in ("Bullish", "Supported") else "v" if x == "Volatile" else ""
    h = res["hist"]
    o = [f"<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Solar Return Generated</title><style>{css}</style></head><body>",
         "<h1>Solar return, generated: NYSE monthly solar-return charts and readings to Dec 2027</h1>",
         "<p class='s'>Built from what Solar return has stated so far: months start when the tropical Sun reaches 27°18' of each sign (the NYSE natal Sun), charts cast for "
         "New York, tropical signs and whole-sign houses. Readings use only the stated indications (debilitated ascendant lord, Mars with Ketu or another malefic in the 8th: "
         "bearish; Venus or Jupiter in the 10th: moderates). Anything Solar return reads that has not been shared to us (other houses, yogas, its own judgement) is not here, "
         "so these are our reconstruction, not Solar return's forecasts. Times US Eastern.</p>"]
    # validation
    o.append("<h2>Check: does the reconstruction give what Solar return said?</h2><div class='wrap'><table><thead><tr><th>Month from</th><th>Indications found</th><th>Generated</th><th>Solar return said</th></tr></thead><tbody>")
    for v in res["validation"]:
        o.append(f"<tr><td>{v['month']}</td><td class='s'>{E('; '.join(v['flags']))}</td><td class='{cls(v['generated'])}'>{v['generated']}</td><td>{E(v['said'])}</td></tr>")
    o.append("</tbody></table></div><div class='wrap'><table><thead><tr><th>Day</th><th>Generated daily call</th><th>Why</th><th>Solar return said</th></tr></thead><tbody>")
    for v in res["week_validation"]:
        ok = (v["generated"] == "Bullish" and v["said"] == "up") or (v["generated"] == "Bearish" and v["said"] == "down")
        o.append(f"<tr><td>{v['d']}</td><td class='{cls(v['generated'])}'>{v['generated']}</td><td class='s'>{E(v['why'])}</td><td>{v['said']} {'✓' if ok else '✗'}</td></tr>")
    o.append("</tbody></table></div>")
    # months
    o.append("<h2>The monthly charts and their readings</h2><div class='wrap'><table><thead><tr><th>Solar month (ET)</th><th>Ascendant</th><th>Ascendant lord</th>"
             "<th>8th house</th><th>10th house</th><th>Generated reading</th><th>This reading since 1928</th></tr></thead><tbody>")
    for m in res["months"]:
        if m["end"] is None:
            continue
        hb = h["by"].get(m["reading"], {})
        rec = f"{hb.get('n', 0)} months: up {hb.get('up', '–')}%, average {hb.get('mean', 0):+.2f}%, fell 5%+ in {hb.get('fall5', '–')}%" if hb else "–"
        o.append(f"<tr><td>{m['start']:%d %b %Y %H:%M} → {m['end']:%d %b %Y}</td><td>{E(m['asc'])}</td><td>{m['lord']}: {E(m['lord_pos'])}</td>"
                 f"<td>{E(', '.join(m['h8']) or '–')}</td><td>{E(', '.join(m['h10']) or '–')}</td><td class='{cls(m['reading'])}'>{m['reading']}</td><td class='s'>{E(rec)}</td></tr>")
    a = h["all"]
    o.append(f"</tbody></table></div><p class='s'>All {a['n']} months 1928–2026: up {a['up']}%, average {a['mean']:+.2f}%, fell 5%+ in {a['fall5']}%. "
             f"Months the generated reading leans bearish: {h['calls']['bear_n']}, of which the S&amp;P rose in {h['calls']['bear_up']}%; leaning supportive: {h['calls']['bull_n']}, rose in {h['calls']['bull_up']}%.</p>")
    for m in res["months"]:
        if m["end"] is None:
            continue
        body = "".join(f"<tr><td><b>{r['body']}</b></td><td>{r['sign']} {r['deg']}</td><td class='n'>{r['house']}</td><td>{'R' if r['retro'] else ''}{' debilitated' if r['neecha'] else ''}</td></tr>" for r in m["rows"])
        o.append(f"<details><summary>Chart {m['start']:%a %d %b %Y %H:%M %Z}: {E(m['asc'])} rising</summary><div class='wrap'><table><thead><tr><th>Planet</th><th>Tropical position</th>"
                 f"<th>House</th><th></th></tr></thead><tbody>{body}</tbody></table></div></details>")
    # transit episodes
    o.append("<h2>Solar return transit rules: when they are active, Nov 2026 – Dec 2027</h2><div class='wrap'><table><thead><tr><th>Rule</th><th>Active (ET dates)</th>"
             "<th>S&amp;P since 1928, next 5 sessions (each episode once)</th><th>Big days</th></tr></thead><tbody>")
    for e in res["episodes"]:
        t = e["record"]
        rec = f"up {t['eps_up5']}% vs {t['eps_exp5']}% (p {t['eps_p']})" if t else "–"
        big = f"{t['big']} vs {t['exp_big']} expected (p {t['p_big']})" if t else "–"
        span = f"{e['frm']:%a %d %b %Y}" + ("" if e["frm"] == e["to"] else f" – {e['to']:%a %d %b %Y}")
        o.append(f"<tr><td>{E(e['rule'])}</td><td>{span}</td><td class='s'>{E(rec)}</td><td class='s'>{E(big)}</td></tr>")
    o.append("</tbody></table></div>")
    # daily
    bd = res["bt_daily"]
    o.append("<h2>Daily calls in the same style, 24 Nov 2026 – 18 Jan 2027</h2><p class='s'>Rules: the bearish aspects (Sun square Mars within 3°, Mars–Ketu within 5°) "
             "take priority; Jupiter sextile Venus within 1° is bullish; Mars square Uranus alone is volatile; otherwise the month's reading. The ordering and the 1° orb were "
             "set so the generated calls match the 9 days Solar return called (16–27 Nov), so the same rule was then run on every S&amp;P session 1928–2026: "
             f"bullish calls right {bd.get('Bullish', {}).get('d1')}% same day / {bd.get('Bullish', {}).get('d5')}% over 5 sessions ({bd.get('Bullish', {}).get('n')} days); "
             f"bearish calls right {bd.get('Bearish', {}).get('d1')}% / {bd.get('Bearish', {}).get('d5')}% ({bd.get('Bearish', {}).get('n')} days); "
             f"the market rose on {bd['_base']['up1']}% of days and over {bd['_base']['up5']}% of 5-session spans.</p>")
    o.append("<div class='wrap'><table><thead><tr><th>Day</th><th>Call</th><th>Why</th><th>Rules active</th></tr></thead><tbody>")
    for r in res["days"]:
        o.append(f"<tr><td>{r['d']:%a %d %b %Y}</td><td class='{cls(r['call'])}'>{r['call']}</td><td class='s'>{E(r['why'])}</td><td class='s'>{E('; '.join(r['active']) or '–')}</td></tr>")
    o.append("</tbody></table></div>")
    o.append("<h2>How much to trust each piece</h2><ul>"
             "<li><b>Monthly chart indications:</b> over 1,186 months they do not call the S&amp;P month; the bearish pair has come before slightly better months (nyse_usa_charts_ET.html).</li>"
             "<li><b>Jupiter sextile Venus:</b> the one transit rule with a modest edge (next 5 sessions up 63.6% vs 55.8%, p 0.03).</li>"
             "<li><b>Sun square Mars:</b> more big days than usual, no direction. <b>Mars–Ketu, Mars square Uranus, Mercury in Pisces:</b> at chance. <b>Mars retrograde:</b> fewer big days.</li>"
             "<li><b>Solar return's own calls so far:</b> " + E("; ".join(f"{f['period']}: {f['score']['status']}" for f in res["scorecard"])) + ".</li></ul>"
             "<p class='s'>Generated by tools/solar_return_generate.py from tools/nyse_charts.py (charts and monthly backtest) and tools/author_forecasts.py (transit tests).</p></body></html>")
    return "".join(o)


if __name__ == "__main__":
    main()
